import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long[] pascalEntries(int[] ns, int[] ks) {
        // Write your solution here
        return new long[ns.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int q = (int) in.nval;
        int[] ns = new int[q], ks = new int[q];
        for (int i = 0; i < q; i++) {
            in.nextToken(); ns[i] = (int) in.nval;
            in.nextToken(); ks[i] = (int) in.nval;
        }
        long[] res = pascalEntries(ns, ks);
        StringBuilder sb = new StringBuilder();
        for (long v : res) sb.append(v).append("\n");
        System.out.print(sb);
    }
}
